class Solution:
    def minimumRemoval(self, beans: List[int]) -> int:
        beans.sort()
        total = sum(beans)
        n = len(beans)
        max_remaining = 0
        for i in range(n):
            max_remaining = max(max_remaining, beans[i] * (n - i))
        return total - max_remaining

class Solution {
public:
    long long minimumRemoval(vector<int>& beans) {
        sort(beans.begin(), beans.end());
        long long total = 0;
        for (int b : beans) total += b;
        long long n = beans.size();
        long long maxRemaining = 0;
        for (long long i = 0; i < n; i++) {
            maxRemaining = max(maxRemaining, (long long)beans[i] * (n - i));
        }
        return total - maxRemaining;
    }
};

class Solution {
    public long minimumRemoval(int[] beans) {
        Arrays.sort(beans);
        long total = 0;
        for (int b : beans) total += b;
        long n = beans.length;
        long maxRemaining = 0;
        for (int i = 0; i < beans.length; i++) {
            maxRemaining = Math.max(maxRemaining, (long) beans[i] * (n - i));
        }
        return total - maxRemaining;
    }
}

var minimumRemoval = function(beans) {
    beans.sort((a, b) => a - b);
    let total = 0n;
    for (const b of beans) total += BigInt(b);
    const n = BigInt(beans.length);
    let maxRemaining = 0n;
    for (let i = 0; i < beans.length; i++) {
        const rem = BigInt(beans[i]) * (n - BigInt(i));
        if (rem > maxRemaining) maxRemaining = rem;
    }
    return Number(total - maxRemaining);
};
